CREATE TABLE brands(id integer PRIMARY KEY, name text NOT NULL);
INSERT INTO brands VALUES(1, 'Fixture Brand');
CREATE TABLE products(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL, price integer NOT NULL, brand_id integer REFERENCES brands(id), visible boolean NOT NULL, created_at timestamptz NOT NULL);
INSERT INTO products(name,price,brand_id,visible,created_at) SELECT 'مصنوعات '||n, n, 1, n<>1205, '2026-10-11T00:00:00Z'::timestamptz FROM generate_series(1,1205) n;
CREATE TABLE bundle_items(bundle_product_id bigint REFERENCES products(id), component_product_id bigint REFERENCES products(id), quantity integer NOT NULL, PRIMARY KEY(bundle_product_id, component_product_id));
INSERT INTO bundle_items VALUES(3,1,2),(3,2,4);
CREATE TABLE settings(key text PRIMARY KEY, value jsonb NOT NULL);
INSERT INTO settings VALUES('shipping', '{"fee":300,"city":"Fixture City"}');
CREATE FUNCTION fixture_total() RETURNS bigint LANGUAGE sql AS 'SELECT sum(price) FROM public.products';
ALTER TABLE products ENABLE ROW LEVEL SECURITY;
CREATE POLICY visible_products ON products FOR SELECT TO fixture_reader USING(visible);
GRANT USAGE ON SCHEMA public TO fixture_reader;
GRANT SELECT ON products TO fixture_reader;
